use super::*;

/// The `[lib]` `path` value a crate at `crate_dir` needs to adopt the SHARED crate root — the
/// third member of the [`marker_for`] / [`dep_for`] family, and relative to the crate for the same
/// depth reason both of those are.
///
/// One file, pointed at by every adopter, so it is byte-identical for all of them BY CONSTRUCTION
/// rather than by a convention somebody has to keep. What makes that possible without collapsing every
/// crate's documentation into one page is that both halves of the shared root come out of `$OUT_DIR`,
/// which is per-crate: `crate.rs` is the crate's modules and `crate_doc.md` is its own `//!` prose.
pub fn lib_path_for(crate_dir: &str) -> String {
    let mut rel = rel_to_materializer(crate_dir);
    rel.push("crate_root.rs".into());
    format!("path = \"{}\"", rel.join("/"))
}
